const { evaluateThrottle, recordDelivery } = require('./throttle');

const DEFAULT_LOCALE = 'en-US';
const PREVIEW_LENGTH = 120;

function validateRecipient(user) {
  if (!user || typeof user !== 'object') {
    throw new TypeError('user is required');
  }
  if (!user.id) {
    throw new TypeError('user.id is required');
  }
}

function validateMessage(message) {
  if (!message || typeof message !== 'object') {
    throw new TypeError('message is required');
  }
  if (!message.title || !message.body) {
    throw new TypeError('message.title and message.body are required');
  }
}

function applyTemplate(value, user, message) {
  return String(value)
    .replace(/\{\{name\}\}/g, user.name || 'there')
    .replace(/\{\{id\}\}/g, user.id)
    .replace(/\{\{category\}\}/g, message.category || 'general');
}

function resolveSettings(defaults, options) {
  const settings = {};
  for (const [key, fallback] of Object.entries(defaults)) {
    settings[key] = options[key] || fallback;
  }
  return settings;
}

/**
 * Builds a notifier by running the shared send pipeline with a channel strategy.
 *
 * A strategy is a plain object:
 * - `channel`: channel name, also the transport method it delivers through
 * - `label`: channel name used in the missing-transport error
 * - `defaultMaxPerHour`: hourly limit when `options.maxPerHour` is not set
 * - `defaults`: channel settings, each overridable by the same key in `options`
 * - `validateUser(user)`: channel-specific checks, run after the shared ones
 * - `throttlePolicies`: ordered policies, see `throttle.js`
 * - `format(base, { user, message, options, settings, now })`: channel payload
 */
function createChannelNotifier(strategy, options = {}) {
  const { channel } = strategy;
  const settings = resolveSettings(strategy.defaults, options);
  const context = {
    channel,
    transport: options.transport || {},
    throttleStore: options.throttleStore || new Map(),
    now: options.now || (() => new Date()),
    defaultLocale: options.defaultLocale || DEFAULT_LOCALE,
    maxPerHour: options.maxPerHour || strategy.defaultMaxPerHour
  };

  function validateUser(user) {
    validateRecipient(user);
    strategy.validateUser(user);
  }

  function shouldThrottle(user, message, sendOptions = {}) {
    return evaluateThrottle(strategy.throttlePolicies, user, message, sendOptions, context);
  }

  function format(user, message, sendOptions = {}) {
    const id = `${channel}-${user.id}-${context.now().getTime()}`;
    const locale = sendOptions.locale || user.locale || context.defaultLocale;
    const title = applyTemplate(message.title, user, message);
    const body = applyTemplate(message.body, user, message);
    const base = {
      id,
      channel,
      locale,
      title,
      body,
      preview: `${title}: ${body}`.slice(0, PREVIEW_LENGTH),
      metadata: {
        category: message.category || 'general',
        priority: message.priority || 'normal',
        generatedAt: context.now().toISOString()
      }
    };

    return strategy.format(base, { user, message, options: sendOptions, settings, now: context.now });
  }

  async function deliver(payload) {
    const { transport } = context;
    if (typeof transport[channel] !== 'function') {
      throw new Error(`${strategy.label} transport is not configured`);
    }
    // Called as a method so transports that rely on `this` keep working.
    await transport[channel](payload);
  }

  async function send(user, message, sendOptions = {}) {
    validateUser(user);
    validateMessage(message);

    const throttle = shouldThrottle(user, message, sendOptions);
    if (throttle.throttled) {
      return {
        channel,
        status: 'throttled',
        reason: throttle.reason,
        retryAt: throttle.retryAt,
        userId: user.id
      };
    }

    const formatted = format(user, message, sendOptions);
    await deliver(formatted);
    recordDelivery(context, user, message);

    return {
      channel,
      status: 'sent',
      userId: user.id,
      id: formatted.id,
      preview: formatted.preview
    };
  }

  return {
    channel,
    send,
    validateUser,
    validateMessage,
    shouldThrottle,
    format,
    deliver
  };
}

module.exports = { createChannelNotifier };

