const { hourlyLimit, requireMarketingOptIn } = require('./throttle');

const E164_PATTERN = /^\+[1-9]\d{6,14}$/;

function truncate(value, maxLength) {
  if (value.length <= maxLength) {
    return value;
  }
  return `${value.slice(0, maxLength - 1)}…`;
}

module.exports = {
  channel: 'sms',
  label: 'sms',
  defaultMaxPerHour: 4,
  defaults: {
    senderId: 'APP',
    segmentLength: 140
  },

  validateUser(user) {
    if (!user.phone || !E164_PATTERN.test(user.phone)) {
      throw new TypeError('user.phone must be E.164 for SMS notifications');
    }
  },

  throttlePolicies: [
    hourlyLimit,
    requireMarketingOptIn('smsOptIn', 'user has not opted into marketing SMS')
  ],

  format(base, { user, message, settings }) {
    const prefix = message.priority === 'urgent' ? 'URGENT: ' : '';
    const text = truncate(`${prefix}${base.title} - ${base.body}`, settings.segmentLength);

    return {
      ...base,
      to: user.phone,
      from: settings.senderId,
      text,
      segments: Math.ceil(text.length / settings.segmentLength),
      preview: text
    };
  }
};

