const { hourlyLimit } = require('./throttle');

const PREVIEW_LENGTH = 120;

// Replies continue an existing thread, so they are never rate limited.
function allowThreadReplies(user, message, options) {
  return options.threadTs ? { throttled: false } : undefined;
}

function blocksFor(formatted, mention) {
  return [
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `${mention}*${formatted.title}*`
      }
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: formatted.body
      }
    },
    {
      type: 'context',
      elements: [
        {
          type: 'mrkdwn',
          text: `Category: ${formatted.metadata.category}`
        }
      ]
    }
  ];
}

module.exports = {
  channel: 'slack',
  label: 'slack',
  defaultMaxPerHour: 20,
  defaults: {
    defaultWorkspace: 'main',
    defaultChannel: '#general'
  },

  validateUser(user) {
    if (!user.slackId && !user.slackChannel) {
      throw new TypeError('user.slackId or user.slackChannel is required for Slack notifications');
    }
  },

  throttlePolicies: [allowThreadReplies, hourlyLimit],

  format(base, { user, options, settings }) {
    const channel = options.channel || user.slackChannel || settings.defaultChannel;
    const mention = user.slackId ? `<@${user.slackId}> ` : '';
    const text = `${mention}*${base.title}*\n${base.body}`;

    return {
      ...base,
      workspace: user.slackWorkspace || settings.defaultWorkspace,
      channel,
      threadTs: options.threadTs || null,
      text,
      blocks: blocksFor(base, mention),
      preview: text.replace(/\*/g, '').slice(0, PREVIEW_LENGTH)
    };
  }
};

