const { MS_PER_HOUR, hourlyLimit } = require('./throttle');

const URGENT_EXPIRY_HOURS = 72;
const DEFAULT_EXPIRY_HOURS = 168;

function allowSecurityAlerts(user, message) {
  return message.category === 'security' ? { throttled: false } : undefined;
}

module.exports = {
  channel: 'inapp',
  label: 'in-app',
  defaultMaxPerHour: 50,
  defaults: {
    defaultIcon: 'bell',
    defaultAction: '/notifications'
  },

  validateUser(user) {
    if (user.disabledInApp) {
      throw new TypeError('in-app notifications are disabled for this user');
    }
  },

  throttlePolicies: [allowSecurityAlerts, hourlyLimit],

  format(base, { user, message, options, settings, now }) {
    const expiresInHours = options.expiresInHours
      || (message.priority === 'urgent' ? URGENT_EXPIRY_HOURS : DEFAULT_EXPIRY_HOURS);
    const expiresAt = new Date(now().getTime() + expiresInHours * MS_PER_HOUR);

    return {
      ...base,
      userId: user.id,
      icon: message.icon || settings.defaultIcon,
      actionUrl: options.actionUrl || message.actionUrl || settings.defaultAction,
      read: false,
      expiresAt: expiresAt.toISOString(),
      preview: base.title
    };
  }
};

