'use strict';
// Characterization probe: original class hierarchy vs composed refactor.
const util = require('node:util');
const path = require('node:path');

const OLD = require('./src/notifications');
const NEW = require(path.join(process.argv[2], 'src/notifications'));

const show = v => util.inspect(v, { depth: Infinity, sorted: false, getters: false });

function steppingClock(stepMs) {
  let t = Date.parse('2026-01-02T03:04:05.000Z');
  return () => {
    const d = new Date(t);
    t += stepMs;
    return d;
  };
}

function loggingTransport(log) {
  return {
    email: async p => { log.push(['email', p]); },
    sms: async p => { log.push(['sms', p]); },
    slack: async p => { log.push(['slack', p]); },
    inapp: async p => { log.push(['inapp', p]); }
  };
}

async function capture(fn) {
  try {
    return { ok: await fn() };
  } catch (err) {
    return { err: [err.constructor.name, err.message] };
  }
}

async function runSequence(impl, channel, notifierOpts, steps) {
  const log = [];
  const throttleStore = new Map();
  const options = { transport: loggingTransport(log), throttleStore, now: steppingClock(notifierOpts.__step || 7), ...notifierOpts };
  delete options.__step;
  const built = await capture(() => impl.createNotifier(channel, options));
  if (built.err) return { built };
  const notifier = built.ok;
  const outcomes = [];
