  { channel: '#ops', locale: 'fr-FR' },
  { actionUrl: '/security', expiresInHours: 5 }
];

const notifierOptions = [
  {},
  { maxPerHour: 1 },
  { maxPerHour: 0 },
  { maxPerHour: 2, __step: 20 * 60 * 1000 },
  {
    maxPerHour: 1,
    from: 'alerts@example.com',
    replyTo: 'help@example.com',
    unsubscribeBaseUrl: 'https://u.test/unsub',
    senderId: 'ACME',
    segmentLength: 40,
    defaultWorkspace: 'product',
    defaultChannel: '#random',
    defaultIcon: 'star',
    defaultAction: '/inbox',
    defaultLocale: 'ja-JP',
    channel: 'ignored'
  }
];

let compared = 0;
const diffs = [];

function check(label, oldValue, newValue) {
  compared += 1;
  const a = show(oldValue);
  const b = show(newValue);
  if (a !== b) diffs.push({ label, old: a, new: b });
}

async function sendMatrix() {
  for (const channel of ['email', 'sms', 'slack', 'inapp']) {
    for (const user of [...users.common, ...users[channel]]) {
      for (const message of messages) {
        for (const sendOpts of sendOptions) {
          for (const notifierOpts of notifierOptions) {
            const steps = Array.from({ length: 4 }, () => [user, message, sendOpts]);
            const label = `${channel} ${show(user)} ${show(message)} ${show(sendOpts)} ${show(notifierOpts)}`;
            check(label, await runSequence(OLD, channel, notifierOpts, steps), await runSequence(NEW, channel, notifierOpts, steps));
          }
        }
      }
    }
  }
}

async function directMethods() {
  const cases = {
    email: [{ id: 'e1', email: 'a@b.c' }, { title: 'Hi {{name}}', body: 'b', category: 'marketing' }],
    sms: [{ id: 's1', phone: '+15551234567' }, { title: 'Hi', body: 'b', priority: 'urgent' }],
    slack: [{ id: 'k1', slackId: 'U1' }, { title: 'Hi', body: 'b' }],
    inapp: [{ id: 'i1' }, { title: 'Hi', body: 'b', category: 'security' }]
  };
  for (const impl of [OLD, NEW]) impl.__trace = [];
  for (const [channel, [user, message]] of Object.entries(cases)) {
    const results = [];
    for (const impl of [OLD, NEW]) {
      const n = impl.createNotifier(channel, { now: steppingClock(3), transport: loggingTransport([]) });
      results.push([
        n.channel,
        await capture(() => n.format(user, message)),
        await capture(() => n.format(user, message, { locale: 'xx' })),
        await capture(() => n.shouldThrottle(user, message)),
        await capture(() => n.shouldThrottle(user, message, { force: true })),
        await capture(() => n.validateUser(user)),
        await capture(() => n.validateUser({ id: 'x' })),
        await capture(() => n.validateMessage({ title: 't' })),
        await capture(() => n.deliver({ p: 1 }))
      ]);
    }
    check(`direct methods ${channel}`, results[0], results[1]);
  }
}

async function transportFailures() {
  const user = {
    email: { id: 'e1', email: 'a@b.c' },
    sms: { id: 's1', phone: '+15551234567' },
    slack: { id: 'k1', slackId: 'U1' },
    inapp: { id: 'i1' }
  };
  const message = { title: 'T', body: 'B' };
  const transports = {
    missing: () => undefined,
    empty: () => ({}),
    notFunction: () => ({ email: 'x', sms: 1, slack: {}, inapp: null }),
    throws: () => ({
      email: async () => { throw new Error('smtp down'); },
      sms: () => { throw new RangeError('sync fail'); },
      slack: async () => { throw new Error('slack 500'); },
      inapp: async () => { throw new Error('db down'); }
    }),
    usesThis: () => {
      const sent = [];
      return {
        sent,
        prefix: 'ctx',
        email(p) { this.sent.push([this.prefix, 'email', p.id]); },
        sms(p) { this.sent.push([this.prefix, 'sms', p.id]); },
        slack(p) { this.sent.push([this.prefix, 'slack', p.id]); },
        inapp(p) { this.sent.push([this.prefix, 'inapp', p.id]); }
      };
    }
  };
  for (const channel of Object.keys(user)) {
    for (const [name, make] of Object.entries(transports)) {
      const results = [];
      for (const impl of [OLD, NEW]) {
        const transport = make();
        const store = new Map();
        const n = impl.createNotifier(channel, { transport, throttleStore: store, now: steppingClock(5) });
        const outcome = await capture(() => n.send(user[channel], message));
        results.push({ outcome, store: [...store.entries()], sent: transport && transport.sent });
      }
      check(`transport ${name} ${channel}`, results[0], results[1]);
    }
  }
}

async function factoryBehavior() {
  for (const channel of ['fax', undefined, null, '', 'EMAIL', 'hasOwnProperty']) {
    check(`createNotifier(${show(channel)})`,
      await capture(() => Object.keys(OLD.createNotifier(channel))),
      await capture(() => Object.keys(NEW.createNotifier(channel))));
  }
  check('registry keys', Object.keys(OLD.registry), Object.keys(NEW.registry));
  check('export names', Object.keys(OLD), Object.keys(NEW).filter(k => k !== '__trace'));

  for (const impl of [OLD, NEW]) impl.__shared = null;
  const shared = [];
  for (const impl of [OLD, NEW]) {
    const log = [];
    const store = new Map();
    const all = impl.createAllNotifiers({ transport: loggingTransport(log), throttleStore: store, maxPerHour: 1, now: steppingClock(11) });
    const outcomes = [];
    outcomes.push(Object.keys(all));
    outcomes.push(await capture(() => all.email.send({ id: 'u', email: 'a@b.c' }, { title: 't', body: 'b' })));
    outcomes.push(await capture(() => all.email.send({ id: 'u', email: 'a@b.c' }, { title: 't', body: 'b' })));
    outcomes.push(await capture(() => all.sms.send({ id: 'u', phone: '+15551234567' }, { title: 't', body: 'b' })));
    outcomes.push(await capture(() => all.inapp.send({ id: 'u' }, { title: 't', body: 'b', category: 'other' })));
    outcomes.push(await capture(() => all.inapp.send({ id: 'u' }, { title: 't', body: 'b', category: 'other' })));
    shared.push({ outcomes, log, store: [...store.entries()] });
  }
  check('createAllNotifiers shared store', shared[0], shared[1]);

  const viaNew = new NEW.registry.email({ transport: loggingTransport([]) });
  check('new registry.email() returns a notifier', 'function', typeof viaNew.send);
}

(async () => {
  await sendMatrix();
  await directMethods();
  await transportFailures();
  await factoryBehavior();
  console.log(`compared ${compared} scenarios, ${diffs.length} differences`);
  for (const d of diffs.slice(0, 10)) {
    console.log(`\n# ${d.label}\n-old ${d.old}\n+new ${d.new}`);
  }
  process.exitCode = diffs.length ? 1 : 0;
})();

